#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos{3, 7, 2};
    if (datos.empty()) {
        std::cout << "Aucune donnée";
    } else {
        datos.at(0) += 4;
        std::cout << "Premier : " << datos.at(0) << "\n";
        std::cout << "Dernier : " << datos.at(datos.size() - 1);
    }
    return 0;
}

